public async Task<Dictionary<int, int>> GetTotalViewsByBlogAsync(
    BlogContext blogContext,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in blogContext.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogGroup
        select new
        {
            BlogId = blogGroup.Key,
            TotalViews = blogGroup.Sum(blogPost => blogPost.Views)
        };

    var results = await query.ToListAsync(cancellationToken);

    return results.ToDictionary(result => result.BlogId, result => result.TotalViews);
}
